from common import *

lessons=[]
def add(*a,**kw):lessons.append(card(*a,**kw))

def geo(points,edges,groups=None,initial=None):
    names=initial or list(points)
    views={'focus':{'label':'Опорные отрезки','segments':edges}}
    for key,(label,segs) in (groups or {}).items():
        extra=list(dict.fromkeys(p for e in segs for p in e if p not in names))
        views[key]={'label':label,'segments':segs}
        if extra:views[key]['points']=extra
    return model(points,edges,names,views)

def aliases(*values):lessons[-1]['answer']['accepted']=list(dict.fromkeys(values))
def ratio(a,b):aliases(f'{a}:{b}',f'{a}/{b}')
def radical_tuple(spec):
    vals=[]
    for style in ('unicode','parenthesized','sqrt','star'):
        terms=[]
        for c,d in spec:
            terms.append(f'{c}√{d}' if style=='unicode' else f'{c}√({d})' if style=='parenthesized' else f'{c}sqrt({d})' if style=='sqrt' else f'{c}*sqrt({d})')
        vals.append(';'.join(terms))
    aliases(*vals)

def midpoint(a,b):return tuple((x+y)/2 for x,y in zip(a,b))
def mix(a,b,t):return tuple((1-t)*x+t*y for x,y in zip(a,b))
T=[['A','B'],['B','C'],['C','A']]

# C1. The angle between altitude RAYS must be distinguished from the angle
# between their supporting lines; an obtuse angle at another vertex changes it.
for part,theta,delta in [('a',46,21),('b',72,18)]:
    h=4/math.tan(math.radians(theta/2));ortho=16/h
    if part=='a':
        pts={'A':(0,h),'B':(-4,0),'C':(4,0),'M':(0,4*h/(math.hypot(4,h)+4)),'P':(0,ortho)}
        edges=T+[['B','M'],['C','M'],['B','P'],['C','P']]
        groups={'bisectors':('Две внутренние биссектрисы',[['B','M'],['C','M']]),'altitudes':('Лучи к ортоцентру',[['B','P'],['C','P']])}
        text='Биссектрисы углов B и C треугольника ABC пересекаются в точке M, а прямые, содержащие высоты треугольника, проведённые из тех же вершин, пересекаются в точке P. Найдите угол BAC, если угол BPC на 21° больше угла BMC.'
        steps=[step('Угол между биссектрисами','Обозначим ∠A = α. В треугольнике BMC углы при B и C равны B/2 и C/2, поэтому ∠BMC = 180° − (B + C)/2 = 90° + α/2.','Сумма углов ABC равна 180°.','bisectors'),step('Положение ортоцентра','Если углы B и C острые, то ∠BPC = 180° − α. Если один из углов B, C тупой, то ∠BPC = α, причём α < 90°. Прямой угол B или C невозможен: тогда P совпадёт с B или C и угол BPC не определён.','Высоты перпендикулярны AC и AB; направление лучей PB, PC выбирает один из двух дополнительных углов.','altitudes'),step('Исключаем второй случай','При тупом B или C было бы α = 90° + α/2 + 21°, то есть α = 222°, что невозможно.','Все углы невырожденного треугольника меньше 180°.','altitudes'),step('Решаем допустимое уравнение','180° − α = 90° + α/2 + 21°. Отсюда 3α/2 = 69°, α = 46°.','Используем именно разность углов, указанную в условии.','altitudes'),step('Проверяем','Угол между биссектрисами равен 113°, между лучами высот — 134°. Разность 134° − 113° = 21°. Ответ: 46°.','Такой треугольник существует, например с углами 46°, 67°, 67°.','bisectors')]
        goal='Угол BAC в градусах'
    else:
        pts={'C':(0,h),'A':(-4,0),'B':(4,0),'K':(0,4*h/(math.hypot(4,h)+4)),'H':(0,ortho)}
        edges=T+[['A','K'],['B','K'],['A','H'],['B','H']]
        groups={'bisectors':('Две внутренние биссектрисы',[['A','K'],['B','K']]),'altitudes':('Лучи к ортоцентру',[['A','H'],['B','H']])}
        text='Биссектрисы углов A и B треугольника ABC пересекаются в точке K, а прямые, содержащие высоты треугольника, проведённые из тех же вершин, пересекаются в точке H. Найдите угол ACB, если угол AHB на 18° меньше угла AKB.'
        steps=[step('Угол между биссектрисами','Обозначим ∠C = γ. Тогда ∠AKB = 180° − (A + B)/2 = 90° + γ/2.','В треугольнике AKB углы при A и B вдвое меньше соответствующих углов ABC.','bisectors'),step('Две конфигурации высот','При острых A и B получаем ∠AHB = 180° − γ. Если A или B тупой, то ∠AHB = γ и γ < 90°. При прямом A или B точка H совпадает с вершиной и данный угол не определён.','Прямые высот перпендикулярны BC и AC; важно учитывать направления лучей.','altitudes'),step('Проверяем случай тупого A или B','Равенство γ = 90° + γ/2 − 18° дало бы γ = 144°. Это противоречит γ < 90° в рассматриваемом случае.','В треугольнике не могут быть два тупых угла.','altitudes'),step('Решаем оставшееся уравнение','180° − γ = 90° + γ/2 − 18°. Значит, 3γ/2 = 108° и γ = 72°.','По условию угол AHB меньше угла AKB на 18°.','altitudes'),step('Проверяем','∠AHB = 108°, ∠AKB = 126°; 126° − 108° = 18°. Ответ: 72°.','Например, треугольник с углами 54°, 54°, 72° удовлетворяет условию.','bisectors')]
        goal='Угол ACB в градусах'
    add('1.4','C',1,part,25,'Биссектрисы и прямые высот',text,goal,theta,'Сначала выразите угол между биссектрисами через искомый угол. Для высот проверьте направление лучей.',steps,geo(pts,edges,groups),caption='Показана одна допустимая конфигурация. Равенство боковых сторон на этой модели не используется в доказательстве; заданные биссектрисы и лучи высот видны сразу.')

# C2. Classification plus justification is checked manually.
for part in ('a','b'):
    if part=='a':
        x=61/34;pts={'B':(0,0),'C':(17,0),'A':(x,math.sqrt(16**2-x*x)),'H':(x,0)};height=['A','H']
        text='Стороны AB, BC и AC треугольника ABC равны 16, 17 и 22 соответственно. Где расположено основание высоты треугольника, проведённой из вершины A: на стороне BC, на её продолжении за точку B или на её продолжении за точку C? Ответ обоснуйте.'
        steps=[step('Угол при B','cos B = (AB² + BC² − AC²)/(2·AB·BC) = (256 + 289 − 484)/(2·16·17) > 0. Значит, B — острый угол.','Теорема косинусов; знаменатель положителен.'),step('Угол при C','cos C = (AC² + BC² − AB²)/(2·AC·BC) = (484 + 289 − 256)/(2·22·17) > 0. Значит, C тоже острый.','Положительный косинус внутреннего угла означает, что угол меньше 90°.'),step('Положение основания','Пусть H — основание высоты AH. Из остроты обоих углов при BC следует, что H находится внутри стороны BC. Дополнительно BH = AB·cos B = 61/34, и 0 < 61/34 < 17.','Основание проекции лежит между концами стороны, если оба прилежащих угла острые.','height')]
        goal='Укажите положение основания высоты и обоснуйте его'
    else:
        x=639/52;pts={'A':(0,0),'C':(26,0),'B':(x,math.sqrt(18**2-x*x)),'H':(x,0)};height=['B','H']
        text='Стороны AB, BC и AC треугольника ABC равны 18, 19 и 26 соответственно. Где расположено основание высоты треугольника, проведённой из вершины B: на стороне AC, на её продолжении за точку A или на её продолжении за точку C? Ответ обоснуйте.'
        steps=[step('Угол при A','cos A = (AB² + AC² − BC²)/(2·AB·AC) = (324 + 676 − 361)/(2·18·26) > 0. Угол A острый.','Знак числителя в теореме косинусов определяет знак косинуса.'),step('Угол при C','cos C = (BC² + AC² − AB²)/(2·BC·AC) = (361 + 676 − 324)/(2·19·26) > 0. Угол C острый.','Все длины положительны, поэтому знаменатель не меняет знак.'),step('Положение основания','Пусть H — основание высоты BH. Оно лежит внутри AC, поскольку оба угла при AC острые. Проверка проекцией: AH = AB·cos A = 639/52, причём 0 < 639/52 < 26.','Положительные проекции со стороны A и со стороны C исключают оба продолжения.','height')]
        goal='Укажите положение основания высоты и обоснуйте его'
    add('1.4','C',2,part,25,'Где лежит основание высоты',text,goal,'','Проверьте знаки косинусов углов при стороне, на которую опущена высота.',steps,geo(pts,T+[height],{'height':('Высота и её основание',[height])}),caption='H обозначает основание указанной в условии высоты. Длины сторон модели соответствуют условию.',mode='manual')

# C3. Coordinates are fixed by the condition; O is an auxiliary intersection.
for part,L,c,page in [('a',16,4,25),('b',44,11,26)]:
    pts={'B':(0,0),'A':(3*L/4,L/2),'C':(3*L/2,-L),'D':(3*L/4,-L/2),'E':(L,0),'O':(3*L/4,0)}
    m=geo(pts,T+[['B','E'],['A','D']],{'intersection':('Перпендикулярные отрезки и точка O',[['A','O'],['O','D'],['B','O'],['O','E']]),'sides':('Три искомые стороны',T)},['A','B','C','D','E'])
    add('1.4','C',3,part,page,'Равные перпендикулярные отрезки',f'В треугольнике ABC биссектриса BE и медиана AD перпендикулярны и имеют одинаковую длину, равную {L}. Найдите стороны треугольника ABC.','Введите AB; BC; AC через точку с запятой',f'{c}√13;{2*c}√13;{3*c}√5','Отразите A относительно BE: отражённая точка попадёт в D.',[
        step('Симметрия относительно биссектрисы','Пусть O = AD ∩ BE. Отражение относительно BE переводит луч BA в луч BC. Поскольку AD ⟂ BE и D лежит на BC, точка A отражается именно в D. Поэтому BA = BD и AO = OD.','Отражённая точка лежит одновременно на прямой AD и луче BC.','intersection'),
        step('Отношение сторон и частей AC',f'Так как D — середина BC, имеем BC = 2AB. По свойству биссектрисы AE : EC = AB : BC = 1 : 2. Кроме того, AO = OD = {L}/2.','Медиана делит противоположную сторону пополам; биссектриса делит сторону в отношении прилежащих сторон.','intersection'),
        step('Удобные координаты',f'Возьмём O(0; 0), B(−x; 0), A(0; {L}/2), D(0; −{L}/2). Из BD = DC получаем C(x; −{L}). Точка E делит AC в отношении 1 : 2, поэтому E(x/3; 0).','Формула внутреннего деления отрезка следует из подобия прямоугольных проекций.','intersection'),
        step('Находим горизонтальную длину',f'BE = x + x/3 = 4x/3 = {L}, откуда x = {3*L//4}.','Точки B, O, E расположены на одной прямой именно в этом порядке.','intersection'),
        step('Вычисляем три стороны',f'AB = √(({3*L//4})² + ({L//2})²) = {c}√13; BC = 2AB = {2*c}√13. Разности координат A и C равны {3*L//4} и {3*L//2}, поэтому AC = {3*c}√5.','Теорема Пифагора применяется к разностям координат; получены положительные стороны единственной формы треугольника с точностью до движения и отражения.','sides')],m,caption='BE — данная биссектриса, AD — данная медиана; оба отрезка видны сразу. Вспомогательная точка O появляется в первом шаге. Перенос начала координат в O не изменяет модель.')
    radical_tuple([(c,13),(2*c,13),(3*c,5)])

# C4. Centroid at origin, perpendicular medians along the coordinate axes.
for part,s in [('a',42),('b',38)]:
    x=3*s/5;y=4*s/5
    pts={'B':(x,0),'C':(0,y),'A':(-x,-y),'G':(0,0),'D':(x/2,y/2),'E':(-x/2,0),'F':(0,-y/2)}
    add('1.4','C',4,part,26,'Третья медиана по двум перпендикулярным',f'Медианы треугольника ABC, проведённые из вершин B и C, пересекаются под прямым углом. Найдите длину медианы треугольника, проведённой из вершины A, если BC = {s}.','Длина медианы из A',3*s//2,'Рассмотрите прямоугольный треугольник BGC, где G — точка пересечения медиан.',[
        step('Обозначаем точку пересечения','Пусть G — точка пересечения медиан, D — середина BC. Тогда BGC — прямоугольный треугольник с прямым углом G, а GD проведён к середине его гипотенузы.','По условию медианы из B и C перпендикулярны.','right'),
        step('Половина гипотенузы',f'GD = BC/2 = {s}/2 = {s//2}.','Медиана прямоугольного треугольника к гипотенузе равна половине гипотенузы.','half'),
        step('Вся медиана',f'Точка G делит AD в отношении AG : GD = 2 : 1. Поэтому AD = 3GD = {3*s//2}.','Три медианы пересекаются в одной точке и делятся ею в отношении 2 : 1 от вершины.','median')],geo(pts,T+[['B','E'],['C','F'],['A','D']],{'right':('Прямоугольный BGC',[['B','G'],['G','C'],['B','C']]),'half':('Медиана GD',[['G','D'],['B','C']]),'median':('Медиана AD',[['A','G'],['G','D']])}),caption='G — точка пересечения медиан; D, E, F — середины противоположных сторон. Их обозначения введены для решения. Модель сохраняет заданную перпендикулярность.')

# C5. A unified cyclic naming avoids accidentally exchanging the requested ratio.
for part,V,W,Z,r,s in [('a','A','B','C',5,4),('b','B','C','A',7,2)]:
    pts={V:(0,0),W:(r,0),Z:(s,math.sqrt(3)*s)}
    pts['M']=midpoint(pts[V],pts[Z]);pts['N']=midpoint(pts[V],pts[W])
    pts['D']=mix(pts[W],pts[Z],r/(r+2*s));pts['K']=mix(pts[W],pts['M'],r/(r+s));pts['L']=mix(pts[Z],pts['N'],4*s/(r+4*s))
    text=('Биссектриса угла A треугольника ABC делит медиану, проведённую из вершины B, в отношении 5 : 4, считая от вершины B. В каком отношении, считая от вершины C, эта биссектриса делит медиану, проведённую из вершины C?' if part=='a' else 'Биссектриса угла B треугольника ABC делит медиану, проведённую из вершины C, в отношении 7 : 2, считая от вершины C. В каком отношении, считая от вершины A, эта биссектриса делит медиану, проведённую из вершины A?')
    add('1.4','C',5,part,26,'Биссектриса пересекает две медианы',text,f'Отношение {Z}L : LN, считая от {Z}',f'{4*s}:{r}','Сравните площади треугольников по общей высоте, а затем по двум равным половинам угла.',[
        step('Обозначения и первая медиана',f'M — середина {V}{Z}, N — середина {V}{W}; K = {W}M ∩ {V}D, L = {Z}N ∩ {V}D. По условию {W}K : KM = {r} : {s}. Поэтому S({V}{W}K) : S({V}KM) = {r} : {s}.','У этих треугольников основания лежат на одной прямой, а высота из общей вершины одинакова.','first'),
        step('Используем середину стороны',f'S({V}KM) = S({Z}KM), так как {V}M = M{Z}. Значит, S({V}K{Z}) = 2S({V}KM), и S({V}{W}K) : S({V}{Z}K) = {r} : {2*s}.','У двух треугольников общая высота из K к стороне, разделённой пополам.','first'),
        step('Переходим к сторонам',f'S({V}{W}K)/S({V}{Z}K) = {V}{W}/{V}{Z}, поскольку у них общая сторона {V}K и равные углы при {V}. Получаем {V}{W} : {V}{Z} = {r} : {2*s}.','Формула S = ab·sin γ/2, а {V}K лежит на биссектрисе.'.replace('{V}',V),'bisector'),
        step('Вторая медиана',f'Аналогично S({V}{W}L)/S({V}{Z}L) = {r}/{2*s}. Но S({V}{W}L) = 2S({V}NL), поскольку N — середина {V}{W}; S({V}{Z}L)/S({V}NL) = {Z}L/LN.','Снова используем равные основания и общие высоты, теперь для медианы из '+Z+'.','second'),
        step('Искомое отношение',f'Следовательно, 2LN/{Z}L = {r}/{2*s}, откуда {Z}L : LN = {4*s} : {r}.','Порядок частей сохраняем от указанной в условии вершины '+Z+'.','second')],geo(pts,T+[[V,'D'],[W,'M'],[Z,'N']],{'first':('Первая медиана',[[W,'M'],[V,'K'],[V,'M'],['M',Z]]),'bisector':('Равные половины угла',[[V,W],[V,'D'],[V,Z]]),'second':('Вторая медиана',[[Z,'N'],[V,'L'],[V,'N'],['N',W]])}),caption=f'M и N — середины сторон, K и L — точки пересечения данных медиан с биссектрисой {V}D. Все обозначения показаны в исходной модели; дополнительных условий на треугольник не предполагается.')
    ratio(4*s,r)

# C7. Incenter division ratio is (AB+AC)/BC, without assuming isosceles.
for part,base,p,q,perim in [('a',7,4,1,35),('b',8,5,2,28)]:
    side=base*p/(2*q);h=math.sqrt(side*side-base*base/4)
    pts={'A':(0,h),'B':(-base/2,0),'C':(base/2,0),'D':(0,0),'I':(0,h*q/(p+q))}
    add('1.4','C',7,part,26,'Инцентр делит биссектрису',f'Точка пересечения биссектрис треугольника ABC делит биссектрису угла BAC в отношении {p} : {q}, считая от вершины A. Найдите периметр треугольника ABC, если BC = {base}.','Периметр ABC',perim,'Примените теорему о биссектрисе сначала к ABC, затем к ABD.',[
        step('Биссектриса во всём треугольнике','Пусть D = AI ∩ BC, I — точка пересечения биссектрис. По теореме о биссектрисе BD = AB·BC/(AB + AC).','AD делит сторону BC в отношении AB : AC.','first'),
        step('Биссектриса в меньшем треугольнике','В треугольнике ABD отрезок BI — биссектриса, поэтому AI/ID = AB/BD = (AB + AC)/BC.','Луч BD совпадает с лучом BC; внутренняя биссектриса B остаётся биссектрисой угла ABD.','second'),
        step('Сумма двух сторон',f'(AB + AC)/{base} = {p}/{q}, поэтому AB + AC = {fmt(base*p/q)}.','Данное отношение отсчитывается от A, то есть относится к AI : ID.','second'),
        step('Периметр',f'P = AB + AC + BC = {fmt(base*p/q)} + {base} = {perim}.','К сумме боковых сторон прибавляем третью сторону.','focus')],geo(pts,T+[['A','D'],['B','I'],['C','I']],{'first':('Биссектриса AD',[['A','D'],['B','D'],['D','C']]),'second':('Биссектриса BI в ABD',[['A','B'],['B','D'],['A','I'],['I','D'],['B','I']])}),caption='I — точка пересечения биссектрис, D — конец биссектрисы из A. Для рисунка выбрана допустимая симметричная форма; доказательство не использует равенство AB и AC.')

# C8. The narrow shape is forced by the data; coordinates are not distorted.
for part,p,q,base,root,c1,c2 in [('a',4,3,14,37,8,6),('b',5,4,18,61,10,8)]:
    t=math.sqrt(base*base-(p+q)**2)
    pts={'A':(0,0),'B':(p*t,p),'C':(q*t,-q),'H':(p*t,0),'K':(q*t,0)}
    add('1.4','C',8,part,26,'Расстояния до биссектрисы',f'Расстояния от вершин B и C треугольника ABC до прямой, содержащей биссектрису угла BAC, равны {p} и {q} соответственно. Найдите длины сторон AB и AC, если BC = {base}.','Введите AB; AC через точку с запятой',f'{c1}√{root};{c2}√{root}','Опустите перпендикуляры к биссектрисе и сравните два прямоугольных треугольника.',[
        step('Основания перпендикуляров',f'Пусть H и K — проекции B и C на прямую биссектрисы. BH = {p}, CK = {q}. Оба основания лежат на луче внутренней биссектрисы, потому что половина угла A меньше 90°. Точки B и C находятся по разные стороны этой прямой.','Расстояние до прямой измеряется перпендикуляром.','heights'),
        step('Подобные треугольники','Треугольники ABH и ACK прямоугольные и имеют равные углы при A. Поэтому AH : AK = AB : AC = BH : CK = '+f'{p} : {q}. Пусть AH = {p}t, AK = {q}t.','Подобие по двум углам; t > 0.','triangles'),
        step('Разности проекций',f'HK = ({p} − {q})t = t. Поперечная разность координат B и C равна BH + CK = {p+q}, поэтому BC² = t² + {p+q}². Отсюда t² = {base}² − {p+q}² = {base*base-(p+q)**2}.','Катеты прямоугольного треугольника между B и C — разности их проекций вдоль и поперёк биссектрисы.','heights'),
        step('Первая сторона',f'AB² = ({p}t)² + {p}² = {p}²(t² + 1) = {p}²·{4*root}, поэтому AB = {c1}√{root}.','Теорема Пифагора для ABH.','triangles'),
        step('Вторая сторона',f'AC = AB·{q}/{p} = {c2}√{root}. Ответ: AB = {c1}√{root}, AC = {c2}√{root}.','Используем уже доказанное отношение гипотенуз подобных треугольников.','triangles')],geo(pts,T+[['A','H'],['B','H'],['C','K']],{'heights':('Данные перпендикулярные расстояния',[['B','H'],['C','K'],['H','K']]),'triangles':('Две прямоугольные проекции',[['A','B'],['B','H'],['A','H'],['A','C'],['C','K'],['A','K']])}),caption='AH — прямая внутренней биссектрисы; H и K — основания данных расстояний. Узкая форма треугольника обусловлена числами условия, масштаб по обеим осям одинаков.')
    radical_tuple([(c1,root),(c2,root)])

# C9/C10 orthic triangle; the original triangle is acute in every model.
def orthic(cosine,side=10,ab=None,with_mid=False):
    if ab is not None:side=ab/math.sqrt(2*(1-cosine))
    sine=math.sqrt(1-cosine*cosine)
    pts={'C':(0,0),'A':(side,0),'B':(side*cosine,side*sine),'K':(side*cosine*cosine,side*cosine*sine),'P':(side*cosine,0)}
    edges=T+[['A','K'],['B','P'],['K','P']]
    if with_mid:
        pts['M']=midpoint(pts['A'],pts['B']);edges += [['M','K'],['M','P']]
    return geo(pts,edges,{'small':('Треугольники CKP и CAB',[['C','K'],['K','P'],['P','C']]),'right':('Два прямых угла',[['A','K'],['K','B'],['A','P'],['P','B']]),'radius':('Радиусы из середины AB',[['M','K'],['M','P'],['A','B']])} if with_mid else {'small':('Треугольник CKP',[['C','K'],['K','P'],['P','C']]),'heights':('Две данные высоты',[['A','K'],['B','P']])})
for part,n,angle in [('a',4,60),('b',2,45)]:
    add('1.4','C',9,part,26 if part=='a' else 27,'Площадь треугольника оснований высот','Точки K и P являются основаниями высот остроугольного треугольника ABC, проведённых из вершин A и B соответственно. Найдите угол ACB, если площадь треугольника CKP '+('вчетверо' if n==4 else 'вдвое')+' меньше площади треугольника ABC.','Угол ACB в градусах',angle,'Выразите CK и CP через стороны, выходящие из C, и cos C.',[
        step('Проекции сторон','Пусть ∠C = γ. Из прямоугольных треугольников CAK и CBP получаем CK = CA·cos γ, CP = CB·cos γ.','Оба основания лежат на сторонах, поскольку ABC остроугольный.','heights'),
        step('Подобие','CK/CA = CP/CB = cos γ, а угол KCP совпадает с углом ACB. Поэтому CKP и CAB подобны с коэффициентом cos γ.','Признак подобия по двум пропорциональным сторонам и углу между ними.','small'),
        step('Отношение площадей',f'S(CKP)/S(ABC) = cos² γ = 1/{n}. Поэтому cos γ = '+('1/2.' if n==4 else '√2/2.'),'Площади подобных треугольников относятся как квадраты соответствующих сторон. Косинус положителен, так как угол острый.','small'),
        step('Искомый угол',f'γ = {angle}°.','На промежутке от 0° до 90° указанное значение косинуса задаёт единственный угол.','small')],orthic(math.cos(math.radians(angle))),caption='K и P — данные основания высот. Показана допустимая остроугольная форма; равенство CA и CB на рисунке не используется в решении.')
    if part=='a':lessons[-1]['pages']=[26,27]
for part,num,den,ab in [('a',3,4,16),('b',2,5,20)]:
    kp=ab*num//den
    add('1.4','C',10,part,27,'Периметр треугольника на высотах',f'Точки K и P являются основаниями высот остроугольного треугольника ABC, проведённых из вершин A и B соответственно, точка M — середина стороны AB. Найдите периметр треугольника MKP, если косинус угла ACB равен {num}/{den}, AB = {ab}.','Периметр MKP',28,'Точки K и P лежат на окружности с диаметром AB.',[
        step('Два прямоугольных треугольника',f'∠AKB = ∠APB = 90°. В каждом из треугольников AKB и APB точка M — середина общей гипотенузы AB. Поэтому MK = MP = AB/2 = {ab//2}.','Медиана к гипотенузе равна её половине.','radius'),
        step('Подобие у вершины C','CK = CA·cos C, CP = CB·cos C. Треугольники CKP и CAB подобны по двум сторонам и углу между ними.','Угол C общий, а отношения соответствующих прилежащих сторон равны cos C.','small'),
        step('Третья сторона',f'KP = AB·cos C = {ab}·{num}/{den} = {kp}.','Сторона KP соответствует AB в доказанном подобии.','small'),
        step('Периметр',f'P(MKP) = MK + MP + KP = {ab//2} + {ab//2} + {kp} = 28.','Складываем три стороны искомого треугольника.','radius')],orthic(num/den,ab=ab,with_mid=True),caption='M — данная середина AB, K и P — данные основания высот. Все стороны искомого MKP видны в исходной модели.')

# C11 similarity fixes the position of P for any permissible shape.
for part,a,b in [('a',5,4),('b',6,5)]:
    pts={'C':(0,0),'A':(a,0),'B':(b/2,b*math.sqrt(3)/2),'P':(b*b/a,0)}
    text=('Точка P выбрана на стороне AC треугольника ABC так, что углы CBP и CAB равны. Найдите отношение площади треугольника CBP к площади треугольника ABP, если AC : BC = 5 : 4.' if part=='a' else 'Точка P выбрана на стороне AC треугольника ABC так, что углы CBP и CAB равны. Найдите отношение AP : PC, если AC : BC = 6 : 5.')
    final='16:9' if part=='a' else '11:25'
    add('1.4','C',11,part,27,'Равные углы дают подобие',text,'Отношение S(CBP) : S(ABP)' if part=='a' else 'Отношение AP : PC',final,'Сопоставьте треугольники CBP и CAB, начиная с общего угла C.',[
        step('Соответствие вершин','Треугольники CBP и CAB подобны: угол C общий, ∠CBP = ∠CAB по условию. Соответствуют C ↔ C, B ↔ A, P ↔ B.','Признак подобия по двум углам.','small'),
        step('Доля стороны AC',f'CP/CB = CB/CA, поэтому CP/CA = (CB/CA)² = {b*b}/{a*a}.','Сначала записываем отношение соответствующих сторон, затем делим на CA.','small'),
        step('Оставшаяся часть',f'AP/AC = 1 − {b*b}/{a*a} = {a*a-b*b}/{a*a}.','P лежит на стороне AC, значит AP + PC = AC.','parts'),
        step('Искомое отношение','S(CBP) : S(ABP) = CP : AP = 16 : 9.' if part=='a' else 'AP : PC = (11/36) : (25/36) = 11 : 25.','Треугольники с вершиной B и основаниями на AC имеют общую высоту.' if part=='a' else 'Общий знаменатель сокращается.','parts')],geo(pts,T+[['B','P']],{'small':('Подобные CBP и CAB',[['C','B'],['B','P'],['P','C']]),'parts':('Части стороны AC',[['A','P'],['P','C'],['B','P']])}))
    ratio(16,9) if part=='a' else ratio(11,25)

# C12 uses the included-angle area formula; no parallelism is assumed.
for part,p,q,r,s,ans1,ans2 in [('a',5,4,3,5,5,19),('b',2,5,1,4,2,33)]:
    pts={'A':(0,0),'B':(9,0),'C':(3,8)};pts['P']=mix(pts['A'],pts['B'],p/(p+q));pts['M']=mix(pts['A'],pts['C'],r/(r+s))
    den=(p+q)*(r+s);num=p*r;g=math.gcd(num,den);numer=num//g;denom=den//g
    add('1.4','C',12,part,27,'Секущая отсекает часть площади',f'Прямая пересекает стороны AB и AC треугольника ABC в точках P и M соответственно. Найдите отношение площади треугольника APM к площади четырёхугольника MCBP, если AP : PB = {p} : {q}, AM : MC = {r} : {s}.','Отношение S(APM) : S(MCBP)',f'{ans1}:{ans2}','Отношение площадей с общим углом равно произведению отношений прилежащих сторон.',[
        step('Части относительно целых сторон',f'AP/AB = {p}/{p+q}, AM/AC = {r}/{r+s}.','В знаменателе доли от целого нужно сложить обе части отношения.','parts'),
        step('Доля маленького треугольника',f'S(APM)/S(ABC) = (AP·AM·sin A)/(AB·AC·sin A) = {p}/{p+q} · {r}/{r+s} = {numer}/{denom}.','Оба треугольника имеют общий угол A; множитель sin A/2 сокращается.','small'),
        step('Оставшийся четырёхугольник',f'S(MCBP)/S(ABC) = 1 − {numer}/{denom} = {denom-numer}/{denom}. Поэтому искомое отношение равно {ans1} : {ans2}.','Секущая PM делит ABC на треугольник APM и четырёхугольник MCBP.','rest')],geo(pts,T+[['P','M']],{'parts':('Деление сторон',[['A','P'],['P','B'],['A','M'],['M','C']]),'small':('Отсечённый APM',[['A','P'],['P','M'],['M','A']]),'rest':('Оставшийся MCBP',[['M','C'],['C','B'],['B','P'],['P','M']])}))
    ratio(ans1,ans2)

# C13–C15 reuse two exact configurations, never assuming the bisector case
# has a midpoint K. Areas are expressed as fractions of the same total S.
def median_model(bisector=False):
    pts={'A':(0,0),'B':(2,0),'C':(3,3*math.sqrt(3))} if bisector else {'A':(0,0),'B':(8,0),'C':(2,6)}
    pts['M']=midpoint(pts['A'],pts['C']);pts['K']=mix(pts['B'],pts['M'],2/5 if bisector else 1/2);pts['P']=mix(pts['B'],pts['C'],1/4 if bisector else 1/3)
    return geo(pts,T+[['B','M'],['A','P']],{'median':('Две половины исходного треугольника',[['B','M'],['A','M'],['M','C']]),'abk':('Треугольник ABK',[['A','B'],['B','K'],['K','A']]),'bkp':('Треугольник BKP',[['B','K'],['K','P'],['P','B']]),'akm':('Треугольник AKM',[['A','K'],['K','M'],['M','A']]),'quad':('Четырёхугольник KPCM',[['K','P'],['P','C'],['C','M'],['M','K']]),'bisector':('Биссектриса AP',[['A','P'],['B','P'],['P','C']])})
mid_text='Через середину K медианы BM треугольника ABC и вершину A проведена прямая, пересекающая сторону BC в точке P. '
bis_text='Медиана BM и биссектриса AP треугольника ABC пересекаются в точке K. Длина стороны AC втрое больше длины стороны AB. '
mid_steps=[
    step('Две половины площади','Обозначим S(ABC) = S. Так как AM = MC, площади ABM и CBM равны S/2.','У этих треугольников равные основания AM, MC и общая высота из B.','median'),
    step('Площадь ABK','K — середина BM, поэтому S(ABK) = S(AKM) = S(ABM)/2 = S/4.','Высота из A к прямой BM общая, а BK = KM.','abk')]
# Position of P by areas: S_ABK=S_BCK because BM is a median, and
# triangles BPK, CPK scale BP:PC. With S_ACK=2S_AKM yields AK:KP=3:1;
# simpler coordinate-free similarity through M parallel AP is available.
mid_position=step('Отношение BP : PC','Проведём мысленно через M прямую, параллельную AP, до встречи с BC в N. В треугольнике CAP точка M — середина CA, поэтому N — середина CP и MN = AP/2. Треугольники BKP и BMN подобны, BK/BM = 1/2, значит BP/BN = 1/2. Следовательно, BP = PN = NC и BP : PC = 1 : 2.','Дважды применяем теорему о средней линии и подобие. Вспомогательную N можно отметить только на этом шаге.','position')
# Add the genuine auxiliary construction only in the corresponding view.
def midpoint_position_model():
    m=median_model();B=m['points']['B'];C=m['points']['C'];m['points']['N']=[(B[i]+2*C[i])/3 for i in range(3)];m['views']['position']={'label':'Параллель через M','segments':[['M','N'],['A','P'],['B','P'],['P','N'],['N','C']],'points':['N']};return m
add('1.4','C',13,'a',27,'Медиана и площадь четырёхугольника',mid_text+'Найдите отношение площади треугольника ABK к площади четырёхугольника KPCM.','Отношение S(ABK) : S(KPCM)','3:5','Сначала найдите долю S(ABK), затем вычтите треугольник BKP из CBM.',mid_steps+[mid_position,
    step('Маленький треугольник у B','S(ABP) = S/3, потому что BP/BC = 1/3. Следовательно, S(BKP) = S(ABP) − S(ABK) = S/3 − S/4 = S/12.','У ABP и ABC общая высота из A к BC; K лежит внутри AP.','bkp'),
    step('Площадь четырёхугольника и отношение','S(KPCM) = S(CBM) − S(BKP) = S/2 − S/12 = 5S/12. Поэтому S(ABK) : S(KPCM) = (S/4) : (5S/12) = 3 : 5.','BM и KP разбивают CBM на указанный четырёхугольник и треугольник BKP.','quad')],midpoint_position_model(),caption='M, K и P — заданные точки. Вспомогательная N и параллель MN появляются только в шаге определения отношения BP : PC.')
ratio(3,5)
bis_steps=[
    step('Биссектриса делит основание','BP : PC = AB : AC = 1 : 3. Поэтому BP/BC = 1/4 и S(ABP) = S/4, где S = S(ABC).','Теорема о биссектрисе и общая высота к BC.','bisector'),
    step('Как K делит медиану','Так как AM = MC, имеем S(ABK) = S(CBK), а S(ACK) = 2S(AKM). С другой стороны, S(ABK)/S(ACK) = AB/AC = 1/3: общая сторона AK и равные половины угла A. Поэтому BK : KM = S(ABK) : S(AKM) = 2 : 3.','Площади с основаниями на BM пропорциональны основаниям; равные половины угла позволяют сократить синус.','median'),
    step('Доли у медианы','S(ABM) = S/2. Отсюда S(ABK) = (2/5)·S/2 = S/5, S(AKM) = (3/5)·S/2 = 3S/10.','Медиана делит общую площадь пополам, а K делит BM в отношении 2 : 3.','abk')]
add('1.4','C',13,'b',27,'Биссектриса и доля площади',bis_text+'Найдите отношение площади треугольника ABK к площади треугольника ABC.','Отношение S(ABK) : S(ABC)','1:5','Используйте отношение BP : PC = 1 : 3 и сравнение площадей при биссектрисе.',bis_steps+[step('Ответ','S(ABK)/S(ABC) = (S/5)/S = 1/5. Искомое отношение 1 : 5.','Все площади выражены через одну и ту же общую площадь S.','abk')],median_model(True));ratio(1,5)
add('1.4','C',14,'a',28,'Две последовательные половины',mid_text+'Найдите отношение площади треугольника ABK к площади треугольника ABC.','Отношение S(ABK) : S(ABC)','1:4','Медиана делит площадь пополам, затем её середина делит одну половину ещё пополам.',mid_steps+[step('Искомая доля','S(ABK)/S(ABC) = (S/4)/S = 1/4. Ответ: 1 : 4.','Обе половины получены по равным основаниям и общей высоте.','abk')],median_model());ratio(1,4)
add('1.4','C',14,'b',28,'Сравнение двух частей',mid_text+'Найдите отношение площади треугольника BKP к площади треугольника AKM.','Отношение S(BKP) : S(AKM)','1:3','Найдите положение P и выразите обе площади через площадь ABC.',mid_steps+[mid_position,
    step('Площадь BKP','BP/BC = 1/3, поэтому S(ABP) = S/3. Тогда S(BKP) = S(ABP) − S(ABK) = S/3 − S/4 = S/12.','K находится между A и P.','bkp'),step('Сравниваем площади','S(BKP) : S(AKM) = (S/12) : (S/4) = 1 : 3.','Площадь AKM была найдена из условия BK = KM.','akm')],midpoint_position_model(),caption='Все заданные точки видны сразу; N и параллель MN — вспомогательное построение для шага о положении P.');ratio(1,3)
for part in ('a','b'):
    tail=[step('Площадь BKP','S(BKP) = S(ABP) − S(ABK) = S/4 − S/5 = S/20.','K лежит внутри AP, поэтому ABP разбивается на ABK и BKP.','bkp')]
    if part=='a':
        tail.append(step('Искомый четырёхугольник','S(KPCM) = S(CBM) − S(BKP) = S/2 − S/20 = 9S/20. Искомое отношение равно 9 : 20.','Медиана BM делит площадь ABC пополам.','quad'));goal='Отношение S(KPCM) : S(ABC)';question='Найдите отношение площади четырёхугольника KPCM к площади треугольника ABC.';answer='9:20'
    else:
        tail.append(step('Искомое отношение','S(BKP) : S(AKM) = (S/20) : (3S/10) = 1 : 6.','Общий множитель S сокращается.','akm'));goal='Отношение S(BKP) : S(AKM)';question='Найдите отношение площади треугольника BKP к площади треугольника AKM.';answer='1:6'
    add('1.4','C',15,part,28,'Площади при биссектрисе и медиане',bis_text+question,goal,answer,'Сначала найдите BK : KM; здесь K не является серединой медианы.',bis_steps+tail,median_model(True));ratio(9,20) if part=='a' else ratio(1,6)

# C16. Establish the correct direction of the altitude foot before using
# the angle-bisector theorem in the right triangle.
pts={'A':(0,0),'B':(4,2*math.sqrt(5)),'C':(3*math.sqrt(5),0),'H':(4,0),'K':(4,4*math.sqrt(5)/5)}
# The entire given bisector ends on BC; its foot D is computed by the theorem.
pts['D']=mix(pts['B'],pts['C'],6/(6+3*math.sqrt(5)))
add('1.4','C',16,'a',28,'Биссектриса делит высоту','Стороны AB и AC треугольника ABC равны 6 и 3√5 соответственно. Найдите площадь треугольника, если биссектриса угла A делит высоту, проведённую из вершины B, в отношении 3 : 2, считая от вершины B.','Площадь ABC',15,'Рассмотрите прямоугольный ABH, где H — основание высоты, K — точка её пересечения с биссектрисой.',[
    step('Расположение основания высоты','Обозначим H — основание высоты BH, K — точку пересечения с биссектрисой. Поскольку K лежит внутри BH и на внутренней биссектрисе A, основание H лежит на луче AC. Тогда AK — биссектриса и в прямоугольном треугольнике ABH.','Проекция луча внутренней биссектрисы на AC положительна: половина угла A меньше 90°.','right'),
    step('Теорема о биссектрисе','BK : KH = AB : AH = 3 : 2. Поэтому AH = 6·2/3 = 4.','В ABH биссектриса AK делит противоположную сторону BH.','split'),
    step('Высота','BH = √(AB² − AH²) = √(36 − 16) = 2√5.','Теорема Пифагора для прямоугольного ABH.','right'),
    step('Площадь','S(ABC) = AC·BH/2 = (3√5)·(2√5)/2 = 15.','BH перпендикулярна прямой AC. Проверка положения: AH = 4 < 3√5 = AC, так что H действительно внутри стороны.','area')],geo(pts,T+[['B','H'],['A','D']],{'right':('Прямоугольный ABH',[['A','B'],['B','H'],['H','A']]),'split':('Деление высоты',[['B','K'],['K','H'],['A','K']]),'area':('Основание AC и высота BH',[['A','C'],['B','H']])}),caption='H — основание заданной высоты, K — её пересечение с биссектрисой AD. Все отрезки условия видны сразу.')
pts={'B':(0,0),'A':(2,2*math.sqrt(15)),'C':(2+6*math.sqrt(5),0),'H':(2,0),'K':(2,2*math.sqrt(15)/5)}
pts['D']=mix(pts['A'],pts['C'],8/(8+pts['C'][0]))
add('1.4','C',16,'b',28,'Высота и два возможных направления','Стороны AB и AC треугольника ABC равны 8 и 4√15 соответственно. Найдите площадь треугольника, если биссектриса угла B делит высоту, проведённую из вершины A, в отношении 4 : 1, считая от вершины A.','Площадь ABC','30√3+2√15','Найдите BH по биссектрисе в ABH, затем высоту AH и положение C.',[
    step('Прямоугольный треугольник у B','Пусть H — основание высоты AH, K — её пересечение с биссектрисой B. Точка H лежит на луче BC: K принадлежит внутренней биссектрисе и отрезку AH, а половина угла B меньше 90°. Следовательно, BK — биссектриса угла ABH.','Это исключает основание высоты на противоположном луче и позволяет применить теорему о биссектрисе.','right'),
    step('Отрезок BH','AK : KH = AB : BH = 4 : 1. Отсюда BH = 8/4 = 2.','Теорема о биссектрисе в треугольнике ABH.','split'),
    step('Высота и второй катет','AH = √(8² − 2²) = 2√15. Затем HC = √(AC² − AH²) = √(240 − 60) = 6√5.','Дважды применяем теорему Пифагора: сначала к ABH, затем к AHC.','right'),
    step('Выбираем расположение C','C лежит на луче BH. Поскольку HC = 6√5 > BH = 2, точка C не может лежать между B и H: тогда HC было бы меньше BH. Значит, порядок точек B–H–C и BC = 2 + 6√5.','Проверяем обе возможные стороны от H и исключаем несовместимую с условием.','base'),
    step('Площадь','S(ABC) = BC·AH/2 = (2 + 6√5)·√15 = 2√15 + 30√3.','Высота AH относится к основанию BC; √75 = 5√3.','area')],geo(pts,T+[['A','H'],['B','D']],{'right':('Два прямоугольных треугольника',[['A','B'],['A','H'],['B','H'],['H','C'],['A','C']]),'split':('Деление высоты',[['A','K'],['K','H'],['B','K']]),'base':('Порядок B–H–C',[['B','H'],['H','C']]),'area':('Основание и высота',[['B','C'],['A','H']])}),caption='H — основание заданной высоты; K лежит на AH и биссектрисе BD. Положение C следует из условия и отдельно обосновывается в решении.')
aliases('30√3+2√15','2√15+30√3','30√(3)+2√(15)','2√(15)+30√(3)','30*sqrt(3)+2*sqrt(15)','2*sqrt(15)+30*sqrt(3)','30sqrt(3)+2sqrt(15)','2sqrt(15)+30sqrt(3)')

# C17. The three exterior triangles are pairwise disjoint and, together
# with ABC, partition A1B1C1; each has area t(1+t) S.
for part,num,den in [('a',2,3),('b',3,2)]:
    t=num/den;pts={'A':(0,0),'B':(6,0),'C':(2,4)}
    pts['A1']=mix(pts['B'],pts['C'],1+t);pts['B1']=mix(pts['C'],pts['A'],1+t);pts['C1']=mix(pts['A'],pts['B'],1+t)
    text=f'На продолжении стороны BC треугольника ABC за точку C взята точка A₁, на продолжении стороны AC за точку A — точка B₁, на продолжении стороны AB за точку B — точка C₁. Найдите отношение площади треугольника '+('A₁B₁C₁ к площади треугольника ABC' if part=='a' else 'ABC к площади треугольника A₁B₁C₁')+f', если A₁C : CB = B₁A : AC = C₁B : BA = {num} : {den}.'
    add('1.4','C',17,part,28,'Три продолжения сторон',text,'Отношение S(A₁B₁C₁) : S(ABC)' if part=='a' else 'Отношение S(ABC) : S(A₁B₁C₁)','13:3' if part=='a' else '4:49','Разбейте большой треугольник на ABC и три внешних треугольника.',[
        step('Одна общая доля',f'Положим t = {num}/{den}, S(ABC) = S. Тогда AB₁ = t·AC, AC₁ = (1 + t)·AB; аналогичные равенства выполняются при циклической замене вершин.','Продолжение добавляет к исходной стороне долю t этой стороны.','extensions'),
        step('Площадь внешнего треугольника','S(AB₁C₁) = t(1 + t)S. Действительно, его стороны из A равны t·AC и (1 + t)·AB, а синус угла B₁AC₁ равен sin A, поскольку этот угол дополнительный к A.','Формула площади по двум сторонам и углу между ними.','one'),
        step('Сумма четырёх площадей','Три внешних треугольника AB₁C₁, BC₁A₁, CA₁B₁ имеют одинаковую площадь t(1 + t)S. Вместе с ABC они без перекрытия заполняют A₁B₁C₁. Поэтому S(A₁B₁C₁)/S = 1 + 3t(1 + t).','Все точки продолжений расположены именно за вершинами, указанными в условии.','outer'),
        step('Подстановка и порядок отношения','1 + 3·(2/3)·(5/3) = 13/3. Ответ: 13 : 3.' if part=='a' else '1 + 3·(3/2)·(5/2) = 49/4. Требуется обратное отношение: S(ABC)/S(A₁B₁C₁) = 4/49, то есть 4 : 49.','Проверяем, какая площадь указана первой.','outer')],geo(pts,T+[['C','A1'],['A','B1'],['B','C1'],['A1','B1'],['B1','C1'],['C1','A1']],{'extensions':('Три заданных продолжения',[['C','A1'],['A','B1'],['B','C1']]),'one':('Один внешний треугольник',[['A','B1'],['B1','C1'],['C1','A']]),'outer':('Большой треугольник',[['A1','B1'],['B1','C1'],['C1','A1']])}),caption='A1, B1, C1 на рисунке обозначают A₁, B₁, C₁ из условия. Точки находятся на заданных продолжениях, отношения длин соблюдены.')
    ratio(13,3) if part=='a' else ratio(4,49)

# C18. Independent exact construction from x=AH, y=HM, x/y=k.
for part,rnum,rden,s,k,cm_ratio,result in [('a',8,7,3,1.5,'16/5','132/5'),('b',3,2,4,4,'3/5','28/5')]:
    y=math.sqrt(2*s/math.sqrt(k*k-1));x=k*y;u=math.sqrt(x*x-y*y);height=2*x+y;v=y*height/u
    A=(-u,0);B=(0,height);C=(v,0);H=(0,y)
    # H lies on AP; HP=2y, AH=x, so P=H+(H-A)*2y/x.
    P=(2*y*u/x,y+2*y*y/x)
    pts={'A':A,'B':B,'C':C,'M':(0,0),'H':H,'P':P}
    ans_num=132 if part=='a' else 28;cm_area='48/5' if part=='a' else '12/5';factor='11/4' if part=='a' else '7/3'
    add('1.4','C',18,part,28 if part=='a' else 29,'Площади между двумя высотами',f'Высоты AP и BM остроугольного треугольника ABC пересекаются в точке H. Найдите площадь четырёхугольника MCPH, если BM : AP = {rnum} : {rden}, а площади треугольников AMH и BPH равны {s} и {4*s} соответственно.','Площадь MCPH',result,'Начните с подобия AMH и BPH: отношение их площадей даёт отношение всех соответствующих длин.',[
        step('Подобие малых треугольников',f'Прямоугольные AMH и BPH подобны: углы при H вертикальные. Из S(BPH)/S(AMH) = {4*s}/{s} = 4 следует BH = 2AH, HP = 2HM, BP = 2AM.','Коэффициент подобия равен квадратному корню из отношения площадей. Остроугольность обеспечивает порядок A–H–P и B–H–M.','small'),
        step('Используем отношение высот',f'Пусть AH = x, HM = y. Тогда BM = 2x + y, AP = x + 2y. Равенство (2x + y)/(x + 2y) = {rnum}/{rden} даёт '+('7(2x + y) = 8(x + 2y), откуда x/y = 3/2.' if part=='a' else '2(2x + y) = 3(x + 2y), откуда x/y = 4.'),'Высоты состоят из отрезков, расположенных по разные стороны H.','altitudes'),
        step('Отношение CM : AM','Пусть AM = u, CM = v. В прямоугольном AMH: u² = x² − y². Треугольники AMH и BMC подобны: у них прямые углы M и ∠MAH = ∠MBC = 90° − C. Поэтому u/(2x + y) = y/v, то есть uv = y(2x + y). Значит, v/u = y(2x + y)/(x² − y²) = '+cm_ratio+'.','Для подстановки достаточно отношения x/y; абсолютные длины вычислять не нужно.','compare'),
        step('Первая часть четырёхугольника',f'Проведём HC. Треугольники CMH и AMH имеют общую высоту HM к AC, поэтому S(CMH) = S(AMH)·CM/AM = {s}·({cm_ratio}) = {cm_area}.','Отношение площадей равно отношению оснований, лежащих на AC.','split'),
        step('Сравниваем две части','Прямоугольные CMB и CPA подобны по общему углу C. Поэтому CM/CP = BM/AP = '+f'{rnum}/{rden}'+'. С учётом HP/HM = 2 получаем S(CPH)/S(CMH) = (CP·HP)/(CM·HM) = '+f'{2*rden}/{rnum}'+'.','Высоты из H к AC и BC равны HM и HP соответственно.','split'),
        step('Складываем площади',f'S(MCPH) = S(CMH) + S(CPH) = ({cm_area})·(1 + {2*rden}/{rnum}) = ({cm_area})·({factor}) = {result}.','Диагональ HC разбивает данный выпуклый четырёхугольник на два треугольника.','split')],geo(pts,T+[['A','P'],['B','M']],{'small':('Подобные AMH и BPH',[['A','M'],['M','H'],['H','A'],['B','P'],['P','H'],['H','B']]),'altitudes':('Две полные высоты',[['A','H'],['H','P'],['B','H'],['H','M']]),'compare':('Подобные AMH и BMC',[['A','M'],['M','H'],['H','A'],['B','M'],['M','C'],['C','B']]),'split':('Две части MCPH',[['M','C'],['C','P'],['P','H'],['H','M'],['H','C']])}),caption='Все заданные точки и обе высоты видны сразу. HC — вспомогательная диагональ: она появляется при разбиении искомого четырёхугольника. Координаты сохраняют обе заданные площади и отношение высот.')
    aliases(result, '26.4' if part=='a' else '5.6', '26,4' if part=='a' else '5,6')

assert len(lessons)==34
assert {(x['number'],x['part']) for x in lessons}=={(n,p) for n in [1,2,3,4,5,*range(7,19)] for p in ('a','b')}
